using Xunit;
using Microsoft.Extensions.Logging;
using Moq;
using MediaBrowser.MediaEncoding.Encoder;

public class EncoderValidatorTests
{
    [Fact]
    public void GetCodecs_LogsErrorAndReturnsEmptyList_WhenExceptionIsThrown()
    {
        // Arrange
        var loggerMock = new Mock<ILogger<EncoderValidator>>();
        var encoderValidator = new EncoderValidator(loggerMock.Object, "fakeEncoderPath");

        var exception = new InvalidOperationException("Test exception");

        // Act
        var result = encoderValidator.GetCodecs(Codec.Encoder);

        // Assert
        loggerMock.Verify(
            logger => logger.LogError(
                It.IsAny<EventId>(),
                It.IsAny<Exception>(),
                It.IsAny<string>(),
                It.IsAny<object[]>()),
            Times.Once);

        Assert.Empty(result);
    }
}
